INSERT INTO "charge_revisions" (
       "rosen_id"
     , "service_start_date"
     , "service_end_date"
     , "revision_reason"

)
VALUES (
       #{rosenId}
     , CAST(#{serviceStartDate} AS date)
     , CAST(#{serviceEndDate} AS date)
     , #{revisionReason}

)
